param([ValidateSet('core','full')][string]$Mode='core')
$ErrorActionPreference='Continue';$root=Split-Path $PSScriptRoot -Parent;$runtime=Join-Path $root '.runtime'
function Get-PortOwner($Port){(Get-NetTCPConnection -LocalPort $Port -State Listen -EA SilentlyContinue|Select-Object -First 1).OwningProcess}
function Test-StateIdentity($State){if($null -eq $State -or -not $State.pid -or -not $State.processStartTimeUtc -or -not $State.port){return $false};try{$p=Get-Process -Id ([int]$State.pid) -EA Stop;$recorded=if($State.processStartTimeUtcTicks){[DateTime]::new([int64]$State.processStartTimeUtcTicks,[DateTimeKind]::Utc)}else{[DateTime]::SpecifyKind(([DateTime]$State.processStartTimeUtc),[DateTimeKind]::Utc)};if([Math]::Abs(($p.StartTime.ToUniversalTime()-$recorded).TotalSeconds)-gt 2){return $false};if((Get-PortOwner ([int]$State.port)) -ne $p.Id){return $false};$cim=Get-CimInstance Win32_Process -Filter "ProcessId=$($p.Id)" -EA Stop;if($State.executablePath -and $cim.ExecutablePath -and $cim.ExecutablePath -ne $State.executablePath){return $false};foreach($marker in @($State.expectedCommandMarkers)){if($marker -like '--port *'){continue};if(-not $cim.CommandLine -or $cim.CommandLine -notlike "*$marker*"){return $false}};return $true}catch{return $false}}
Get-ChildItem (Join-Path $runtime '*.json') -EA SilentlyContinue|ForEach-Object {$file=$_;try{$state=Get-Content -Raw $file.FullName|ConvertFrom-Json}catch{Write-Warning "Unreadable state retained: $($file.FullName)";return};if(-not(Test-StateIdentity $state)){if(Get-Process -Id ([int]$state.pid) -EA SilentlyContinue){Write-Warning "Refusing to stop unverifiable PID $($state.pid) for $($state.service). State retained.";return};Remove-Item -LiteralPath $file.FullName -Force;Write-Host "Removed stale state for $($state.service).";return};try{Stop-Process -Id ([int]$state.pid) -Force -EA Stop}catch{Write-Warning "Could not stop verified PID $($state.pid): $($_.Exception.Message)";return};for($i=0;$i -lt 10 -and(Get-Process -Id ([int]$state.pid) -EA SilentlyContinue);$i++){Start-Sleep 1};if(Get-Process -Id ([int]$state.pid) -EA SilentlyContinue){Write-Warning "PID $($state.pid) did not exit; state retained for inspection.";return};Remove-Item -LiteralPath $file.FullName -Force;Write-Host "Stopped $($state.service) (PID $($state.pid))."}
Push-Location $root;try{docker compose stop}finally{Pop-Location}
